WITH driver_race_counts AS (
    SELECT drive_link as drv_main, COUNT(*) as race_count
    FROM driver_standings 
    GROUP BY drive_link
)
SELECT drv_main, race_count FROM driver_race_counts ORDER BY race_count DESC LIMIT 10;

